<?php
declare(strict_types=1);
require dirname(__DIR__, 2) . '/bootstrap.php';
use App\Core\Auth;use App\Core\Csrf;use App\Core\Database;
Auth::requireAdmin();$pdo=Database::connection();
$mode=in_array((string)($_GET['mode']??'manual'),['manual','automated'],true)?(string)$_GET['mode']:'manual';
$events=$pdo->query("SELECT e.id,e.name,e.event_date FROM bdc_events e LEFT JOIN bdc_scoring_archived_events a ON a.event_id=e.id WHERE e.status NOT IN ('completed','published') AND a.event_id IS NULL ORDER BY e.event_date DESC,e.name")->fetchAll();
$occupied=$pdo->query("SELECT DISTINCT event_id,dance_style,division FROM bdc_scoring_rounds WHERE status<>'archived'")->fetchAll();
$stmt=$pdo->prepare("SELECT r.*,e.name event_name,e.status event_status,(SELECT COUNT(*) FROM bdc_scoring_entries x WHERE x.round_id=r.id) entry_count,(SELECT COUNT(*) FROM bdc_scoring_judges x WHERE x.round_id=r.id) judge_count,(SELECT COUNT(*) FROM bdc_scoring_marks x WHERE x.round_id=r.id) mark_count,(SELECT COUNT(*) FROM bdc_scoring_final_marks x WHERE x.round_id=r.id) final_mark_count FROM bdc_scoring_rounds r JOIN bdc_events e ON e.id=r.event_id LEFT JOIN bdc_scoring_archived_events a ON a.event_id=e.id WHERE e.status NOT IN ('completed','published') AND a.event_id IS NULL AND r.status NOT IN ('completed','archived') AND r.scoring_mode=:mode ORDER BY r.updated_at DESC LIMIT 30");
$stmt->execute(['mode'=>$mode]);$rounds=$stmt->fetchAll();$csrf=Csrf::token();
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Scoring Dashboard | BDC</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light">
